public class VolatileFlagExample {
    // volatile ensures immediate visibility across threads
    private volatile boolean shutdownRequested = false;

    public void worker() {
        while (!shutdownRequested) {
            // Perform continuous background work
        }
        System.out.println("Worker thread gracefully stopped.");
    }

    public void requestShutdown() {
        this.shutdownRequested = true; // Immediately visible to the worker thread
    }
}
